// COURTSIM-WIRE-025 -- WHO SITS IN THE JURY BOX, in seat order.
//
// The first six are the shipped cast and are unchanged. Seats 7-12 are only
// reached when JURY_SIZE is 12, and they are listed here rather than
// generated so the cost of twelve is visible at the point of decision:
//
//   * spectator_2 (m014), spectator_4 (m019), spectator_9 (f017) are the
//     three unseated COURTSIM-ASSETS-023 civilians. These are free.
//   * spectator_5 (m169) is a POLICE UNIFORM and spectator_6 (m301) is
//     SPORTS KIT. ASSETS-023 section 2 kept both out of the GALLERY because
//     a uniformed officer reads as a second bailiff and a tracksuit reads as
//     a bug. In a JURY BOX a police officer is worse, not better: police are
//     routinely struck from juries. Listed, flagged, not pretended away.
//   * seat 12 REPEATS spectator_7 (f009), who is also in the gallery. There
//     are 21 identities and twelve jurors needs 22 seats filled. The two
//     copies are 6 m apart on opposite sides of the bar, which is the least
//     bad placement, and it is still a duplicate.
//
// If the founder wants twelve, the clean answer is three more Rocketbox
// civilian conversions through tools/build_spectators.py -- that lane's
// script, not this one's file.
const JURY_ROLES = [
  'juror_1', 'juror_2', 'juror_3', 'juror_4', 'juror_5', 'juror_6',
  'spectator_2', 'spectator_4', 'spectator_9',   // m014, m019, f017 -- civilians
  'spectator_5', 'spectator_6',                  // m169 POLICE, m301 SPORTS KIT
  'spectator_7',                                 // f009 -- DUPLICATE of a gallery seat
];
const JURORS = (() => {
  const out = [];
  for (let k = 0; k < JURY_PER_ROW; k++) {
    for (let row = 0; row < JURY_ROWS; row++) {
      const tierH = row === 0 ? JURY_TIER_FRONT_H : JURY_TIER_BACK_H;
      out.push({
        pos: [row === 0 ? JURY_ROW_X_FRONT : JURY_ROW_X_BACK, tierH, jurySeatZ(row, k)],
        seatY: tierH + CHAIR_SEAT_H,
        role: JURY_ROLES[row * JURY_PER_ROW + k],
        chairArms: true,
      });
    }
  }
  // Emit in the shipped order -- the whole front row, then the whole back
  // row -- because the load queue order is what decides which figures arrive
  // first, and a reordered queue is a behaviour change nobody asked for.
  return out.sort((a, b) => (a.pos[0] - b.pos[0]) || (a.pos[2] - b.pos[2]));
})();
// =========================================================================
// COURTSIM-WIRE-025 -- THE ASSERTION THAT MAKES JURY_SIZE SAFE TO TOUCH.
//
// Every number above is derived, and a derivation that quietly disagrees
// with the six coordinates this room was built, rendered and signed off
// around would be exactly the kind of silent regression this project keeps
// paying for. So at the shipped size it is CHECKED, not trusted, at module
// load, against the literals that used to be here.
// =========================================================================
if (JURY_SIZE === 6) {
  const EXPECTED = [
    [JURY_ROW_X_FRONT, -1.0, 'juror_1'], [JURY_ROW_X_FRONT, -0.2, 'juror_2'],
    [JURY_ROW_X_FRONT, 0.6, 'juror_3'], [JURY_ROW_X_BACK, -0.6, 'juror_4'],
    [JURY_ROW_X_BACK, 0.2, 'juror_5'], [JURY_ROW_X_BACK, 1.0, 'juror_6'],
  ];
  const bad = [];
  if (JURORS.length !== 6) bad.push(`count ${JURORS.length}`);
  else {
    JURORS.forEach((j, i) => {
      const [x, z, role] = EXPECTED[i];
      if (Math.abs(j.pos[0] - x) > 1e-9 || Math.abs(j.pos[2] - z) > 1e-9 || j.role !== role) {
        bad.push(`seat ${i}: got (${j.pos[0]}, ${j.pos[2]}, ${j.role}) want (${x}, ${z}, ${role})`);
      }
    });
  }
  if (Math.abs(JURY_BOX_Z_MIN + 1.75) > 1e-9 || Math.abs(JURY_BOX_Z_MAX - 1.35) > 1e-9) {
    bad.push(`box Z ${JURY_BOX_Z_MIN}..${JURY_BOX_Z_MAX} want -1.75..1.35`);
  }
  if (bad.length) {
    console.error('[courtsim] JURY_LAYOUT_REGRESSED at JURY_SIZE=6 -- the derived '
      + 'layout no longer reproduces the shipped six seats:', bad);
  }
} else {
  console.warn(`[courtsim] JURY_SIZE=${JURY_SIZE}: the jury box is built for ${JURY_SIZE} `
    + `at a ${JURY_SEAT_PITCH} m seat pitch, box Z ${JURY_BOX_Z_MIN.toFixed(2)}..${JURY_BOX_Z_MAX.toFixed(2)}. `
    + 'Seats 10 and 11 are a police uniform and sports kit, and seat 12 repeats a '
    + 'gallery identity -- see JURY_ROLES. This is not the shipped configuration.');
}

// MEASURED, caught in review: the ceiling troffers were a fixed 3x3 grid at
// x,z in {-4, 0, 4}, and Courtroom B's coffer beams run at z in {-4, 0, 4}
// -- so in the one venue that has beams, every one of the nine fixtures had
// a 0.15 m beam through the middle of it, cutting each 0.5 m emissive panel
// in half. The grid is now venue-aware and returned from ONE function, used
// by both the real geometry and the environment map that has to agree with
// it, so the two can never drift apart. For a coffered ceiling the fixtures
// land in the CENTRES of the coffers, which is where a real coffered
// ceiling puts them anyway.
function ceilingFixtureGrid(v) {
  const xs = v.ceilingStyle === 'coffered' ? [-3, 0, 3] : [-4, 0, 4];
  const zs = v.ceilingStyle === 'coffered' ? [-2, 2, 6] : [-4, 0, 4];
  const out = [];
  for (const x of xs) for (const z of zs) out.push([x, z]);
  return out;   // always 9 entries, x-major
}

// DEFECT 4 -- the one place a facing yaw is decided, for every figure in
// the room. Model forward is +Z (established by this file's own
// LIPSYNC-INVISIBLE-001 finding and re-used by setActiveSpeaker's
// atan2(dx, dz) below), so aiming a figure at a point is a single atan2.
function yawToward(fromX, fromZ, toX, toZ) {
  return Math.atan2(toX - fromX, toZ - fromZ);
}

